		return result, err
	}
	publications, publishErr := s.publishReviewStage(ctx, sp)
	result.Publications = append(result.Publications, publications...)
	if publishErr != nil {
		return result, publishErr
	}
	_ = os.RemoveAll(reviewerRoot)
	_ = now
	if result.Verdict == ReviewFail {
		return result, fmt.Errorf("review completed with failing verdict")
	}
	for sessionID := range completedSessionIDs {
		_ = s.deleteCompletedSession(ctx, sessionID)
	}
	return result, nil
}

