	EvidenceID         string                `json:"evidenceId,omitempty"`
	Evidence           []EvidenceReference   `json:"evidence,omitempty"`
	Issues             []SmokeIssue          `json:"issues,omitempty"`
	Override           *DiagnosticOverride   `json:"override,omitempty"`
}

type SmokeError struct {
	Code, Category, Message, Guidance string
	Err                               error
}

func (e *SmokeError) Error() string {
	if e == nil {
		return ""
	}
	if e.Err != nil {
		return fmt.Sprintf("smoke %s: %s: %v", e.Category, e.Message, e.Err)
	}
	return fmt.Sprintf("smoke %s: %s", e.Category, e.Message)
}
func (e *SmokeError) Unwrap() error {
	if e == nil {
		return nil
	}
	return e.Err
}

func smokeError(code, category, message, guidance string, err error) error {
	return &SmokeError{Code: code, Category: category, Message: message, Guidance: guidance, Err: err}
}

func AsSmokeError(err error) (*SmokeError, bool) {
	var target *SmokeError
	ok := errors.As(err, &target)
	return target, ok
}

func validSmokeVerdict(v SmokeVerdict) bool {
	switch v {
	case SmokePass, SmokePassWithOpenIssues, SmokeFailVerdict, SmokeBlockedVerdict, SmokeNotApplicable:
		return true
	}
	return false
}

func validateSmokeStageState(root string, sp Sprint, state SmokeStageState, path string) error {
	switch state.Status {
	case SmokeReady, SmokeRunning, SmokeCompleted, SmokeFailed, SmokeCancelled:
	default:
		return fmt.Errorf("%w: %s: smoke has unsupported status %q", ErrFlowStateMalformed, path, state.Status)
	}
	if state.Verdict != "" && !validSmokeVerdict(state.Verdict) {
		return fmt.Errorf("%w: %s: smoke has unsupported verdict %q", ErrFlowStateMalformed, path, state.Verdict)
	}
	if state.Path != ArtifactRelPath(sp, StageSmoke) {
		return fmt.Errorf("%w: %s: smoke path mismatch", ErrFlowStateMalformed, path)
	}
	if _, err := resolveSprintContained(root, sp, state.Path); err != nil {
		return fmt.Errorf("%w: %s: unsafe smoke path: %v", ErrFlowStateMalformed, path, err)
	}
	for _, d := range state.Diagnostics {
		if len(d) > 240 {
			return fmt.Errorf("%w: %s: smoke diagnostic too long", ErrFlowStateMalformed, path)
		}
	}
	if err := validateAttempt(state.ActiveAttempt, true); err != nil {
		return fmt.Errorf("%w: %s: smoke active attempt: %v", ErrFlowStateMalformed, path, err)
	}
	if err := validateAttempt(state.LastAttempt, false); err != nil {
		return fmt.Errorf("%w: %s: smoke last attempt: %v", ErrFlowStateMalformed, path, err)
	}
	if state.Override != nil {
		if !state.Override.Requested || !state.Override.Confirmed || strings.TrimSpace(state.Override.Rationale) == "" || len(state.Override.Rationale) > 240 || strings.ContainsAny(state.Override.Rationale, "\x00\r\n") {
			return fmt.Errorf("%w: %s: invalid diagnostic override", ErrFlowStateMalformed, path)
		}
	}
	for _, issue := range state.Issues {
		if issue.ID == "" || (issue.Status != "open" && issue.Status != "resolved") {
			return fmt.Errorf("%w: %s: invalid smoke issue", ErrFlowStateMalformed, path)
		}
	}
	if state.LastComplete != nil {
		if state.LastComplete.Artifact != ArtifactRelPath(sp, StageSmoke) || state.LastComplete.CompletedAt.IsZero() || state.LastComplete.InputFingerprint == "" || state.LastComplete.ArtifactDigest == "" {
			return fmt.Errorf("%w: %s: invalid smoke lastComplete", ErrFlowStateMalformed, path)
		}
	}
	return nil
}

func derefTime(value *time.Time) time.Time {
	if value == nil {
		return time.Time{}
	}
	return value.UTC()
}

func SaveFlowState(root string, s Sprint, state FlowState) error {
	// Planning-stage refreshes must not erase the last complete verification
	// evidence. Explicit stage writers load and replace their own record.
	if state.Review == nil || state.Smoke == nil || state.QA == nil {
		if prior, err := LoadFlowState(root, s); err == nil {
			if state.Review == nil {
				state.Review = prior.Review
			}
			if state.Smoke == nil {
				state.Smoke = prior.Smoke
			}
			if state.QA == nil {
				state.QA = prior.QA
			}
		} else if !errors.Is(err, ErrFlowStateMissing) {
			return err
		}
	}
	if authoritative, err := FlowStateInDatabase(root, s); err != nil {
		return err
	} else if authoritative {
		if err := saveFlowStateDatabase(root, s, state); err != nil {
			return err
		}
		if !flowStateCheckpoint(state) {
			return nil
		}
		return saveFlowStateWithHooks(root, s, state, atomicWriteHooks{})
	}
	return saveFlowStateWithHooks(root, s, state, atomicWriteHooks{})
}

func flowStateCheckpoint(state FlowState) bool {
	for _, stage := range state.Stages {
		if stage.Status != StatusComplete && stage.Status != StatusFailed && stage.Status != StatusSkipped {
			return false
		}
	}
	return len(state.Stages) > 0
}

func saveFlowStateWithHooks(root string, s Sprint, state FlowState, hooks atomicWriteHooks) error {
	path, err := FlowStatePath(root, s)
	if err != nil {
		return err
	}
	state.UpdatedAt = time.Now().UTC()
	if err := ValidateFlowState(root, s, state, path); err != nil {
		return err
	}
	content, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal flow state %s: %w", path, err)
	}
	content = append(content, '\n')
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("create flow state directory %s: %w", filepath.Dir(path), err)
	}
	temp, err := os.CreateTemp(filepath.Dir(path), ".flow-state.*.tmp")
	if err != nil {
		return fmt.Errorf("create temporary flow state %s: %w", path, err)
	}
	tempPath := temp.Name()
	cleanup := true
	defer func() {
		if cleanup {
			_ = os.Remove(tempPath)
		}
	}()
	if _, err := temp.Write(content); err != nil {
		_ = temp.Close()
		return fmt.Errorf("write temporary flow state %s: %w", tempPath, err)
	}
	if err := temp.Sync(); err != nil {
		_ = temp.Close()
		return fmt.Errorf("flush temporary flow state %s: %w", tempPath, err)
	}
	if err := temp.Close(); err != nil {
		return fmt.Errorf("close temporary flow state %s: %w", tempPath, err)
	}
	if hooks.BeforeRename != nil {
		if err := hooks.BeforeRename(path); err != nil {
			return fmt.Errorf("prepare flow state rename %s: %w", path, err)
		}
	}
	if err := os.Rename(tempPath, path); err != nil {
		return fmt.Errorf("rename flow state %s: %w", path, err)
	}
	cleanup = false
	syncDir(filepath.Dir(path))
	return nil
}

func ValidateFlowState(root string, s Sprint, state FlowState, path string) error {
	if state.SchemaVersion == 0 {
		return fmt.Errorf("%w: %s: missing schemaVersion", ErrFlowStateMalformed, path)
	}
	if state.SchemaVersion != FlowStateSchemaVersion {
		return fmt.Errorf("%w: %s: schemaVersion %d", ErrFlowStateUnsupported, path, state.SchemaVersion)
	}
	if state.Project == "" || state.Sprint == "" || state.UpdatedAt.IsZero() {
		return fmt.Errorf("%w: %s: missing required top-level fields", ErrFlowStateMalformed, path)
	}
	if state.Project != s.Project {
		return fmt.Errorf("%w: %s: project mismatch %q", ErrFlowStateMalformed, path, state.Project)
	}
	if state.Sprint != s.Slug {
		return fmt.Errorf("%w: %s: sprint mismatch %q", ErrFlowStateMalformed, path, state.Sprint)
	}
	if len(state.Stages) != len(PlanningStages()) {
		return fmt.Errorf("%w: %s: expected %d stages", ErrFlowStateMalformed, path, len(PlanningStages()))
	}
	seen := map[PlanningStage]bool{}

